CREATE DATABASE IF NOT EXISTS tssmt_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tssmt_db;
CREATE TABLE admins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE members (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, member_id VARCHAR(20) UNIQUE NULL, full_name VARCHAR(150) NOT NULL, mobile VARCHAR(20) NOT NULL UNIQUE, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NULL, status ENUM('pending','active','rejected','inactive') NOT NULL DEFAULT 'pending', photo VARCHAR(255) NULL, address TEXT NULL, district VARCHAR(100) NULL, state VARCHAR(100) NULL, pin VARCHAR(12) NULL, occupation VARCHAR(120) NULL, approved_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE membership_payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, member_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL, payment_mode ENUM('upi','bank','cash') NOT NULL, transaction_no VARCHAR(100) NULL UNIQUE, payment_date DATE NOT NULL, proof_path VARCHAR(255) NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', remarks TEXT NULL, approved_by BIGINT UNSIGNED NULL, approved_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (member_id) REFERENCES members(id), FOREIGN KEY (approved_by) REFERENCES admins(id)) ENGINE=InnoDB;
CREATE TABLE donations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, member_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL, purpose VARCHAR(255) NOT NULL, payment_mode ENUM('upi','bank','cash') NOT NULL, transaction_no VARCHAR(100) NULL UNIQUE, payment_date DATE NOT NULL, proof_path VARCHAR(255) NULL, remarks TEXT NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', approved_by BIGINT UNSIGNED NULL, approved_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (member_id) REFERENCES members(id), FOREIGN KEY (approved_by) REFERENCES admins(id)) ENGINE=InnoDB;
CREATE TABLE acknowledgements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, acknowledgement_no VARCHAR(30) NOT NULL UNIQUE, member_id BIGINT UNSIGNED NOT NULL, payment_type ENUM('membership','donation') NOT NULL, source_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL, issued_at DATETIME NOT NULL, UNIQUE KEY receipt_source (payment_type, source_id), FOREIGN KEY (member_id) REFERENCES members(id)) ENGINE=InnoDB;
CREATE TABLE notices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, audience ENUM('public','members','both') NOT NULL DEFAULT 'both', publish_date DATE NOT NULL, expiry_date DATE NULL, attachment VARCHAR(255) NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE activities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, activity_date DATE NOT NULL, location VARCHAR(200) NULL, description TEXT NOT NULL, main_image VARCHAR(255) NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', featured TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE activity_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, activity_id BIGINT UNSIGNED NOT NULL, image_path VARCHAR(255) NOT NULL, FOREIGN KEY (activity_id) REFERENCES activities(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE site_settings (`key` VARCHAR(100) PRIMARY KEY, `value` TEXT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE cms_content (`key` VARCHAR(100) PRIMARY KEY, title VARCHAR(200) NULL, body TEXT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, admin_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, record_type VARCHAR(50) NOT NULL, record_id BIGINT UNSIGNED NOT NULL, ip_address VARCHAR(45) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (admin_id) REFERENCES admins(id)) ENGINE=InnoDB;
INSERT INTO site_settings (`key`,`value`) VALUES ('org_name','TSSMT'),('short_name','TSSMT'),('membership_fee','0'),('membership_validity','1 Year'),('membership_description','Annual membership fee'),('footer_text','TSSMT'),('ack_footer','Thank you for your support.'),('authorised_signatory_name',''),('authorised_signatory_designation','') ON DUPLICATE KEY UPDATE `value`=VALUES(`value`);
INSERT INTO cms_content (`key`,title,body) VALUES ('home_intro','Serving the community','A simple, transparent way to join and support TSSMT.'),('mission','Our Mission','To serve the community with dignity and purpose.'),('about','About Us','Update this content from the admin panel.'),('contact','Contact','Update contact information from the admin panel.') ON DUPLICATE KEY UPDATE body=VALUES(body);
